<script setup lang="ts">
import{computed,onMounted,ref}from'vue'
import{FileUp,KeyRound,Play,RefreshCw,ShieldCheck,Terminal,Upload,X}from'lucide-vue-next'
import{listCredentials,type Credential}from'@/api/cmdb'
import{useAuthStore}from'@/stores/useAuthStore'
type Asset={id:string;name:string;ip:string;projectGroup:string;status:string};type HostKey={id:string;assetId:string;host:string;port:number;keyType:string;fingerprint:string;addedBy:string;createdAt:string};type HostKeyProbe={assetId:string;host:string;port:number;keyType:string;fingerprint:string;publicKey:string;trusted:boolean;changed:boolean;trustedFingerprint:string};type Grant={id:string;subjectType:string;subject:string;assetId:string;projectGroup:string;permissions:string[];enabled:boolean;createdBy:string};type SessionLog={time:string;level:string;message:string};type Session={id:string;assetId:string;assetName:string;ip:string;credentialId:string;operator:string;status:string;createdAt:string;expiresAt:string;logs:SessionLog[]}
const auth=useAuthStore(),assets=ref<Asset[]>([]),grants=ref<Grant[]>([]),sessions=ref<Session[]>([]),credentials=ref<Credential[]>([]),selectedAssetId=ref(''),selectedSessionId=ref(''),credentialId=ref(''),command=ref('uptime'),uploadPath=ref('/tmp/upload.bin'),downloadPath=ref('/etc/os-release'),busy=ref(false),error=ref(''),message=ref(''),uploadFile=ref<File>(),hostKeys=ref<HostKey[]>([]),hostProbe=ref<HostKeyProbe>()
const grantForm=ref({subjectType:'user',subject:'admin',scopeType:'project',assetId:'',projectGroup:'',permissions:['terminal','file']})
const headers=computed(()=>({Authorization:`Bearer ${auth.token}`,'Content-Type':'application/json'})),selectedSession=computed(()=>sessions.value.find(item=>item.id===selectedSessionId.value)),projectGroups=computed(()=>[...new Set(assets.value.map(item=>item.projectGroup).filter(Boolean))])
async function request<T>(url:string,init?:RequestInit){const response=await fetch(url,{...init,headers:init?.body instanceof FormData?{Authorization:`Bearer ${auth.token}`}:headers.value});if(!response.ok){let detail=`请求失败 (${response.status})`;try{const body=await response.json() as{message?:string};detail=body.message||detail}catch{}throw new Error(detail)}return response.status===204?undefined as T:response.json() as Promise<T>}
async function load(){busy.value=true;error.value='';try{const[assetPage,gs,ss,cs,hks]=await Promise.all([request<{data:Asset[]}>('/api/v1/cmdb/assets?page=1&pageSize=100&type=server'),request<Grant[]>('/api/v1/discovery/access-grants'),request<Session[]>('/api/v1/discovery/remote-sessions'),listCredentials(auth.token),request<HostKey[]>('/api/v1/discovery/remote-host-keys')]);assets.value=assetPage.data;grants.value=gs;sessions.value=ss;credentials.value=cs;hostKeys.value=hks;if(!selectedAssetId.value&&assets.value.length)selectedAssetId.value=assets.value[0].id;if(!selectedSessionId.value&&sessions.value.length)selectedSessionId.value=sessions.value[0].id}catch(e){error.value=e instanceof Error?e.message:'远程运维数据加载失败'}finally{busy.value=false}}
async function createGrant(){try{const scope=grantForm.value.scopeType==='project'?{projectGroup:grantForm.value.projectGroup,assetId:''}:{assetId:grantForm.value.assetId,projectGroup:''};await request('/api/v1/discovery/access-grants',{method:'POST',body:JSON.stringify({subjectType:grantForm.value.subjectType,subject:grantForm.value.subject,permissions:grantForm.value.permissions,...scope})});message.value='授权已创建';await load()}catch(e){error.value=e instanceof Error?e.message:'授权创建失败'}}
async function toggleGrant(item:Grant){try{await request(`/api/v1/discovery/access-grants/${item.id}/toggle`,{method:'POST'});await load()}catch(e){error.value=e instanceof Error?e.message:'授权状态更新失败'}}
async function removeGrant(item:Grant){if(!confirm(`删除 ${item.subject} 的远程访问授权？`))return;try{await request(`/api/v1/discovery/access-grants/${item.id}`,{method:'DELETE'});await load()}catch(e){error.value=e instanceof Error?e.message:'授权删除失败'}}
async function probeHostKey(){try{hostProbe.value=await request<HostKeyProbe>('/api/v1/discovery/remote-host-keys/probe',{method:'POST',body:JSON.stringify({assetId:selectedAssetId.value,credentialId:credentialId.value})});message.value='主机指纹已探测，请确认后信任'}catch(e){error.value=e instanceof Error?e.message:'主机指纹探测失败'}}
async function trustHostKey(){if(!hostProbe.value)return;try{await request('/api/v1/discovery/remote-host-keys',{method:'POST',body:JSON.stringify(hostProbe.value)});hostProbe.value=undefined;message.value='主机指纹已信任';await load()}catch(e){error.value=e instanceof Error?e.message:'主机指纹信任失败'}}
async function removeHostKey(item:HostKey){if(!confirm(`删除 ${item.host} 的主机指纹信任？`))return;try{await request(`/api/v1/discovery/remote-host-keys/${item.id}`,{method:'DELETE'});message.value='主机指纹信任已删除';await load()}catch(e){error.value=e instanceof Error?e.message:'删除主机指纹失败'}}
async function createSession(){try{const item=await request<Session>('/api/v1/discovery/remote-sessions',{method:'POST',body:JSON.stringify({assetId:selectedAssetId.value,credentialId:credentialId.value})});selectedSessionId.value=item.id;message.value='远程会话已建立';await load()}catch(e){error.value=e instanceof Error?e.message:'会话建立失败'}}
async function execute(){try{await request(`/api/v1/discovery/remote-sessions/${selectedSessionId.value}/command`,{method:'POST',body:JSON.stringify({command:command.value})});await load()}catch(e){error.value=e instanceof Error?e.message:'命令执行失败'}}
async function upload(){if(!uploadFile.value)return;const form=new FormData();form.append('file',uploadFile.value);form.append('path',uploadPath.value);try{await request(`/api/v1/discovery/remote-sessions/${selectedSessionId.value}/upload`,{method:'POST',body:form});message.value='文件上传完成';await load()}catch(e){error.value=e instanceof Error?e.message:'文件上传失败'}}
async function download(){try{const response=await fetch(`/api/v1/discovery/remote-sessions/${selectedSessionId.value}/download?path=${encodeURIComponent(downloadPath.value)}`,{headers:{Authorization:`Bearer ${auth.token}`}});if(!response.ok)throw new Error(`下载失败 (${response.status})`);const blob=await response.blob();const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=downloadPath.value.split('/').pop()||'download.bin';link.click();URL.revokeObjectURL(url);message.value='文件下载完成'}catch(e){error.value=e instanceof Error?e.message:'文件下载失败'}}
async function closeSession(){try{await request(`/api/v1/discovery/remote-sessions/${selectedSessionId.value}`,{method:'DELETE'});message.value='远程会话已关闭';await load()}catch(e){error.value=e instanceof Error?e.message:'关闭会话失败'}}
onMounted(load)
</script>
<template><section class="remote-access"><header><div><h2>远程终端与文件传输</h2><span>基于资产级授权，命令和文件操作全部审计</span></div><button @click="load"><RefreshCw :class="{spin:busy}"/></button></header><div v-if="error" class="access-error">{{error}}</div><div class="access-grid"><section class="access-card"><h3><ShieldCheck/>账户授权</h3><div class="access-form"><select v-model="grantForm.subjectType"><option value="user">用户</option><option value="role">角色</option></select><input v-model="grantForm.subject" placeholder="用户或角色"><select v-model="grantForm.scopeType"><option value="project">项目组</option><option value="asset">指定资产</option></select><select v-if="grantForm.scopeType==='project'" v-model="grantForm.projectGroup"><option value="">选择项目组</option><option v-for="group in projectGroups" :key="group">{{group}}</option></select><select v-else v-model="grantForm.assetId"><option value="">选择资产</option><option v-for="asset in assets" :key="asset.id" :value="asset.id">{{asset.name}} · {{asset.ip}}</option></select><label><input v-model="grantForm.permissions" type="checkbox" value="terminal">终端</label><label><input v-model="grantForm.permissions" type="checkbox" value="file">文件</label><button class="primary" @click="createGrant">新增授权</button></div><div class="grant-list"><article v-for="item in grants" :key="item.id" :class="{disabled:!item.enabled}"><KeyRound/><div><strong>{{item.subjectType}} · {{item.subject}}</strong><span>{{item.projectGroup||item.assetId}} · {{item.permissions.join(' / ')}}</span></div><button @click="toggleGrant(item)">{{item.enabled?'停用':'启用'}}</button><button @click="removeGrant(item)">删除</button></article></div></section><section class="access-card"><h3><ShieldCheck/>主机指纹</h3><div class="access-form"><button @click="probeHostKey">探测当前资产指纹</button><div v-if="hostProbe" class="host-key-probe"><span>{{hostProbe.keyType}}</span><code>{{hostProbe.fingerprint}}</code><b v-if="hostProbe.changed">指纹已变更，原指纹：{{hostProbe.trustedFingerprint}}</b><button class="primary" @click="trustHostKey">{{hostProbe.trusted?'更新信任':'信任指纹'}}</button></div><div class="grant-list"><article v-for="item in hostKeys" :key="item.id"><KeyRound/><div><strong>{{item.host}}:{{item.port}}</strong><span>{{item.fingerprint}}</span></div><button @click="removeHostKey(item)">删除</button></article></div></div></section><section class="access-card"><h3><Terminal/>远程会话</h3><div class="access-form"><select v-model="selectedAssetId"><option v-for="asset in assets" :key="asset.id" :value="asset.id">{{asset.name}} · {{asset.ip}}</option></select><select v-model="credentialId"><option value="">默认凭据</option><option v-for="credential in credentials.filter(item=>item.kind==='ssh')" :key="credential.id" :value="credential.id">{{credential.name}}</option></select><button class="primary" :disabled="!selectedAssetId" @click="createSession">建立会话</button><select v-model="selectedSessionId"><option value="">选择会话</option><option v-for="session in sessions" :key="session.id" :value="session.id">{{session.assetName}} · {{session.operator}} · {{session.status}}</option></select><button :disabled="!selectedSessionId" @click="closeSession"><X/>关闭</button></div><div class="terminal-box"><div class="command-row"><input v-model="command" @keyup.enter="execute" placeholder="输入远程命令"><button :disabled="!selectedSessionId" @click="execute"><Play/>执行</button></div><pre v-if="selectedSession"><span v-for="log in selectedSession.logs" :key="log.time+log.message" :data-level="log.level"><em>{{log.time}}</em>{{log.message}}</span></pre><div v-else class="empty-access">建立或选择会话后开始执行</div></div></section><section class="access-card"><h3><FileUp/>文件传输</h3><label>上传目标路径<input v-model="uploadPath"></label><input type="file" @change="uploadFile=($event.target as HTMLInputElement).files?.[0]"><button :disabled="!selectedSessionId||!uploadFile" @click="upload"><Upload/>上传</button><label>下载远程路径<input v-model="downloadPath"></label><button :disabled="!selectedSessionId" @click="download">下载</button><p>单文件限制：上传 50MB，下载 25MB。路径不允许包含 `..`。</p></section></div><div v-if="message" class="access-message">{{message}}</div></section></template>
<style scoped>.remote-access{margin:18px 20px;padding:18px;border:1px solid #18384a;border-radius:12px;background:#071925}.remote-access>header{display:flex;justify-content:space-between;align-items:center}.remote-access h2{margin:4px 0}.remote-access header span{color:#6f91a5;font-size:11px}.access-grid{display:grid;grid-template-columns:1fr 1.3fr 1fr;gap:12px;margin-top:14px}.access-card{padding:13px;border:1px solid #173a52;background:#081f31}.access-card h3{display:flex;align-items:center;gap:7px;font-size:13px}.access-form{display:grid;gap:7px}.access-form input,.access-form select{border:1px solid #22465f;background:#061725;color:#dcecff;padding:8px}.access-form label{font-size:11px;color:#7894a8}.grant-list article{display:grid;grid-template-columns:20px 1fr 50px 50px;gap:6px;align-items:center;padding:8px 0;border-top:1px solid #123043}.grant-list article.disabled{opacity:.5}.grant-list span{display:block;color:#6f91a5;font-size:10px}.grant-list button{padding:4px 5px;font-size:10px}.terminal-box{margin-top:10px}.command-row{display:flex;gap:6px}.command-row input{flex:1}.terminal-box pre{min-height:240px;max-height:360px;overflow:auto;white-space:pre-wrap;background:#020b12;color:#bae6fd;padding:10px;font:11px monospace}.terminal-box pre span{display:block;margin-bottom:8px}.terminal-box em{color:#4f7188;font-style:normal;margin-right:8px}.terminal-box span[data-level=error]{color:#fb7185}.empty-access{padding:30px;text-align:center;color:#64869a}.access-card p{color:#6f91a5;font-size:10px}.access-error,.access-message{margin-top:10px;padding:9px;border:1px solid #7b3140;background:#351723;color:#ff9cad}.access-message{border-color:#155e75;background:#082b38;color:#a5f3fc}@media(max-width:1200px){.access-grid{grid-template-columns:1fr}}</style>